//! Intranet name normalization (spec §15.9.2 item 5, vectors in §22.5).
//!
//! The character data is Unicode 15.1.0 and comes from the panel's table
//! file (`nametable-unicode-15.1.0.txt`, generated by the panel's
//! `config/scripts/gen_mesh_name_table.py`), embedded byte for byte so the
//! panel and the kernel turn every name into the same label. The standard
//! library's character functions follow newer Unicode versions and use full
//! lowercase mappings, so they are not used here.

use std::collections::HashMap;
use std::sync::OnceLock;

/// The table file, identical to the panel's copy.
pub(crate) const TABLE_TEXT: &str = include_str!("nametable-unicode-15.1.0.txt");
/// SHA-256 of [`TABLE_TEXT`]; the panel's test checks the same digest.
pub const TABLE_SHA256: &str = "f1f486fd79d9fd8b15183a5d4d1a6efa801af64c6744973d0c65ba958010cd7c";
/// Longest DNS label, in bytes.
pub const MAX_LABEL_BYTES: usize = 63;

struct Table {
    /// Sorted, disjoint ranges of non-ASCII code points of category L* or Nd.
    keep: Vec<(u32, u32)>,
    /// Simple lowercase mapping.
    lower: HashMap<u32, u32>,
}

impl Table {
    fn parse(text: &str) -> Result<Self, String> {
        let mut keep: Vec<(u32, u32)> = Vec::new();
        let mut lower = HashMap::new();
        for (number, line) in text.lines().enumerate() {
            let line = line.trim_end_matches('\r');
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let fields: Vec<&str> = line.split_whitespace().collect();
            let &[kind, from, to] = fields.as_slice() else {
                return Err(format!("name table line {}", number + 1));
            };
            let (from, to) = (code_point(from), code_point(to));
            let (Some(from), Some(to)) = (from, to) else {
                return Err(format!("name table line {}", number + 1));
            };
            match kind {
                "keep" => {
                    if to < from || keep.last().is_some_and(|last| from <= last.1) {
                        return Err(format!("name table line {}: out of order", number + 1));
                    }
                    keep.push((from, to));
                }
                "lower" => {
                    lower.insert(from, to);
                }
                _ => return Err(format!("name table line {}", number + 1)),
            }
        }
        if keep.is_empty() || lower.is_empty() {
            return Err("name table is empty".into());
        }
        Ok(Self { keep, lower })
    }

    fn kept(&self, c: u32) -> bool {
        let index = self.keep.partition_point(|range| range.1 < c);
        self.keep.get(index).is_some_and(|range| range.0 <= c)
    }
}

/// A code point written in 4 to 6 upper-case hexadecimal digits.
fn code_point(text: &str) -> Option<u32> {
    if !(4..=6).contains(&text.len())
        || !text
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'A'..=b'F').contains(&b))
    {
        return None;
    }
    u32::from_str_radix(text, 16)
        .ok()
        .filter(|c| *c <= 0x10FFFF)
}

fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| Table::parse(TABLE_TEXT).expect("embedded name table is valid"))
}

/// The intranet name label of `raw` (a host name or a name from the panel),
/// or an empty string when nothing is left (no record is made then).
pub fn normalize_label(raw: &str) -> String {
    let table = table();
    let mapped: Vec<char> = raw
        .chars()
        .map(|c| {
            let code = u32::from(c);
            let code = table.lower.get(&code).copied().unwrap_or(code);
            let c = char::from_u32(code).unwrap_or('-');
            let kept = c.is_ascii_lowercase()
                || c.is_ascii_digit()
                || c == '-'
                || (!c.is_ascii() && table.kept(code));
            if kept {
                c
            } else {
                '-'
            }
        })
        .collect();
    let mut label: Vec<char> = trim_hyphens(&mapped).to_vec();
    loop {
        if label.iter().all(char::is_ascii) {
            label.truncate(MAX_LABEL_BYTES);
            while label.last() == Some(&'-') {
                label.pop();
            }
            return label.into_iter().collect();
        }
        let encoded = format!("xn--{}", punycode(&label));
        if encoded.len() <= MAX_LABEL_BYTES {
            return encoded;
        }
        // Never cut the encoded form: drop a character before encoding.
        label.pop();
        while label.last() == Some(&'-') {
            label.pop();
        }
    }
}

/// Whether `label` is already the normalized form of itself: what the
/// panel sends and what a query may ask for.
pub fn is_normalized(label: &str) -> bool {
    !label.is_empty() && label.is_ascii() && normalize_label(label) == label && !is_bad_ace(label)
}

/// An ASCII label that starts like an encoded one must decode to a label
/// this rule produces; checking that needs the decoder, so a label is
/// accepted only when it encodes back to itself.
fn is_bad_ace(label: &str) -> bool {
    let Some(encoded) = label.strip_prefix("xn--") else {
        return false;
    };
    match decode_punycode(encoded) {
        Some(chars) => {
            let text: String = chars.into_iter().collect();
            normalize_label(&text) != label
        }
        None => true,
    }
}

fn trim_hyphens(chars: &[char]) -> &[char] {
    let start = chars.iter().position(|c| *c != '-').unwrap_or(chars.len());
    let end = chars
        .iter()
        .rposition(|c| *c != '-')
        .map_or(start, |i| i + 1);
    &chars[start..end]
}

// Punycode parameters (RFC 3492 §5).
const BASE: u32 = 36;
const T_MIN: u32 = 1;
const T_MAX: u32 = 26;
const SKEW: u32 = 38;
const DAMP: u32 = 700;
const INITIAL_BIAS: u32 = 72;
const INITIAL_N: u32 = 128;

fn digit(d: u32) -> char {
    char::from(b"abcdefghijklmnopqrstuvwxyz0123456789"[d as usize])
}

fn adapt(delta: u32, points: u32, first: bool) -> u32 {
    let mut delta = if first { delta / DAMP } else { delta / 2 };
    delta += delta / points;
    let mut k = 0;
    while delta > ((BASE - T_MIN) * T_MAX) / 2 {
        delta /= BASE - T_MIN;
        k += BASE;
    }
    k + (BASE - T_MIN + 1) * delta / (delta + SKEW)
}

/// Punycode encoding (RFC 3492 §6.3) of a label of at most 63 code points;
/// no overflow is possible at that length.
fn punycode(label: &[char]) -> String {
    let mut out: String = label.iter().filter(|c| c.is_ascii()).collect();
    let basic = out.len() as u32;
    let total = label.len() as u32;
    if basic > 0 {
        out.push('-');
    }
    let (mut n, mut delta, mut bias, mut handled) = (INITIAL_N, 0u32, INITIAL_BIAS, basic);
    while handled < total {
        let next = label
            .iter()
            .map(|c| u32::from(*c))
            .filter(|c| *c >= n)
            .min()
            .unwrap_or(n);
        delta += (next - n) * (handled + 1);
        n = next;
        for c in label.iter().map(|c| u32::from(*c)) {
            if c < n {
                delta += 1;
            }
            if c != n {
                continue;
            }
            let mut q = delta;
            let mut k = BASE;
            loop {
                let t = k.saturating_sub(bias).clamp(T_MIN, T_MAX);
                if q < t {
                    break;
                }
                out.push(digit(t + (q - t) % (BASE - t)));
                q = (q - t) / (BASE - t);
                k += BASE;
            }
            out.push(digit(q));
            bias = adapt(delta, handled + 1, handled == basic);
            delta = 0;
            handled += 1;
        }
        delta += 1;
        n += 1;
    }
    out
}

/// Punycode decoding (RFC 3492 §6.2) of the part after `xn--`; `None` for
/// anything malformed or overflowing.
fn decode_punycode(input: &str) -> Option<Vec<char>> {
    if !input.is_ascii() || input.len() > MAX_LABEL_BYTES {
        return None;
    }
    let (basic, rest) = match input.rfind('-') {
        Some(at) => (&input[..at], &input[at + 1..]),
        None => ("", input),
    };
    let mut out: Vec<char> = basic.chars().collect();
    let (mut n, mut i, mut bias) = (INITIAL_N, 0u32, INITIAL_BIAS);
    let mut bytes = rest.bytes().peekable();
    while bytes.peek().is_some() {
        let old_i = i;
        let mut w = 1u32;
        let mut k = BASE;
        loop {
            let byte = bytes.next()?;
            let d = match byte {
                b'a'..=b'z' => u32::from(byte - b'a'),
                b'0'..=b'9' => u32::from(byte - b'0') + 26,
                _ => return None,
            };
            i = i.checked_add(d.checked_mul(w)?)?;
            let t = k.saturating_sub(bias).clamp(T_MIN, T_MAX);
            if d < t {
                break;
            }
            w = w.checked_mul(BASE - t)?;
            k += BASE;
        }
        let points = u32::try_from(out.len()).ok()? + 1;
        bias = adapt(i - old_i, points, old_i == 0);
        n = n.checked_add(i / points)?;
        i %= points;
        let c = char::from_u32(n)?;
        if c.is_ascii() {
            return None;
        }
        out.insert(i as usize, c);
        i += 1;
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_the_panels_file() {
        let digest = ring::digest::digest(&ring::digest::SHA256, TABLE_TEXT.as_bytes());
        let hex: String = digest.as_ref().iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!(hex, TABLE_SHA256);
        assert!(TABLE_TEXT.contains("Unicode 15.1.0"));
        // Parses: lazily built on first use.
        assert!(table().kept(0x4E2D)); // 中
        assert!(!table().kept(0x2460)); // ① is No
        assert_eq!(table().lower.get(&0x130), Some(&0x69)); // İ → i
    }

    /// Spec §22.5.
    #[test]
    fn spec_vectors() {
        let cities = "北京上海广州深圳杭州南京成都重庆武汉西安天津苏州长沙郑州青岛";
        assert_eq!(cities.chars().count(), 30);
        let pair = |input: &str, output: &str| (input.to_owned(), output.to_owned());
        let vectors = [
            pair("中国", "xn--fiqs8s"),
            pair("Bücher", "xn--bcher-kva"),
            pair("香港 01", "xn---01-by5gj66p"),
            pair(
                cities,
                "xn--fhq3ob536bhjr1rcwim2eba12nmcw58c4qr78mkhd0rglncb29td03a4nd",
            ),
            pair("e\u{301}x", "e-x"),
            pair("①号机", "xn--rpr216b"),
            pair("٣", "xn--cib"),
            pair("İstanbul", "istanbul"),
            pair("ΟΔΟΣ", "xn--pxavbq"),
            (format!("{}-b", "a".repeat(62)), "a".repeat(62)),
            (format!("{}é", "a".repeat(60)), "a".repeat(60)),
            pair(
                "北京上海广州深圳杭州南京成都重庆武汉西 安天津苏州",
                "xn--fhq3ob536bhjr1rnqnba06lfc366cwwq5fm24ce3f36brv1ukg2a6hd",
            ),
            pair("！！", ""),
            pair("a\u{105C0}b", "a-b"),
        ];
        for (input, output) in vectors {
            assert_eq!(normalize_label(&input), output, "{input}");
            assert!(output.len() <= MAX_LABEL_BYTES);
        }
    }

    /// `docs/architecture/mesh-module.md`, name normalization.
    #[test]
    fn module_doc_vectors() {
        assert_eq!(normalize_label("Café"), "xn--caf-dma");
        assert_eq!(normalize_label("cafe\u{301}"), "cafe");
        assert_eq!(normalize_label("e\u{301}te"), "e-te");
        assert_eq!(normalize_label(&"a".repeat(70)), "a".repeat(63));
        assert_eq!(
            normalize_label(&"中".repeat(85)),
            format!("xn--fiqa{}", "a".repeat(55))
        );
        assert_eq!(
            normalize_label("北京市海淀区中关村软件园二期第十八号楼研发中心东区"),
            "xn--fiqwikd7mo2ikbz2sbilct0ie2oq1wz80a5tam4xr7qq9ae35j2jm4x2h"
        );
    }

    #[test]
    fn ascii_and_edges() {
        assert_eq!(normalize_label("Build_01"), "build-01");
        assert_eq!(normalize_label("--web--"), "web");
        assert_eq!(normalize_label(""), "");
        assert_eq!(normalize_label("   "), "");
        assert_eq!(normalize_label("a.b"), "a-b");
    }

    #[test]
    fn normalized_labels() {
        for label in ["build-01", "xn--fiqs8s", "a", "xn--bcher-kva"] {
            assert!(is_normalized(label), "{label}");
        }
        for label in [
            "",
            "Build",
            "-a",
            "a-",
            "a.b",
            "a_b",
            "中国",
            "xn--",
            "xn--zzzzzzz9",
            "xn--abc",
        ] {
            assert!(!is_normalized(label), "{label}");
        }
        // Incomplete Punycode.
        assert!(!is_normalized("xn--bcher-kv"));
        // Decodes to control characters, which the rule replaces.
        assert!(!is_normalized("xn--abc"));
    }

    #[test]
    fn punycode_round_trips() {
        for text in ["中国", "bücher", "香港-01", "٣", "οδοσ"] {
            let chars: Vec<char> = text.chars().collect();
            let encoded = punycode(&chars);
            assert_eq!(decode_punycode(&encoded), Some(chars), "{text}");
        }
    }
}
